  (205, 2, 11, 'Oraimo FreePods 4 ANC True Wireless Earbuds', 'Oraimo', 24500, 42000, 5, '1,284', 12, 1, '🎧', NULL, NULL, 0, '{"brand":"Oraimo","model":"OTW-330","sku":"ORA-FP4-BLK","sold":"5,000+","ratings":1284,"stock":12,"sellerRating":92,"crumbs":[["Electronics","category.html?c=electronics"],["Headphones & Earphones",null],["Wireless Earbuds",null]],"colors":[["Black","#222222"],["White","#eeeeee"],["Blue","#3b6cb0"],["Green","#3b8a5a"]],"styles":["Standard","With Charging Case","With Ear Hooks"],"desc":["The Oraimo FreePods 4 delivers immersive Active Noise Cancellation that silences up to 90% of surrounding noise, so your music, calls and podcasts always sound clean. A 4-microphone ENC system keeps your voice crisp on every call, while the latest Bluetooth 5.3 chipset pairs instantly and holds a rock-solid connection. Enjoy up to 40 hours of total playtime when you charge with the included case.","Built for all-day comfort, the lightweight in-ear design sits securely without pressure, and IPX5 water resistance shrugs off sweat and light rain. Responsive touch controls let you play, pause, switch tracks and answer calls with a tap. When you''re in a hurry, a quick 10-minute fast charge gives you up to 2 hours of playback."],"features":["Active Noise Cancellation with Transparency mode","4-mic ENC for crystal-clear calls","Up to 40 hours total playtime with case","Bluetooth 5.3 ultra-low latency game mode","IPX5 sweat and splash resistant","Fast charge: 10 minutes for 2 hours of playback"],"specs":[["Brand","Oraimo"],["Model","OTW-330"],["Bluetooth","5.3"],["Noise cancellation","Active (ANC) + Transparency"],["Playtime","Up to 40 hours with case"],["Water resistance","IPX5"],["Charging port","USB-C"],["Warranty","12 months"]]}'),
